     const payload={name:f.name.value,query:{language:query.language,query:query.query,limit:1000},interval:Number(f.interval.value),lookback:Number(f.lookback.value),threshold:mode==='rows'?Number(f.threshold.value):1,trigger,enabled:f.enabled.checked};
     if(mode==='rows'&&f.case_enabled.checked)payload.case_adapter={entity_field:f.entity_field.value,risk_score:Number(f.risk_score.value),severity:f.case_severity.value,cooldown:Number(f.cooldown.value),mitre:[]};
     await post('/api/rules',payload);await rules();notify('판정 기준과 사건 연결 설정을 저장했습니다.');
