   function update(){const aggregate=f.trigger_mode.value==='aggregate';d.querySelector('[data-row-controls]').hidden=aggregate;d.querySelector('[data-aggregate-controls]').hidden=!aggregate;f.threshold.required=!aggregate;f.aggregate_field.required=aggregate;f.aggregate_value.required=aggregate;f.case_enabled.disabled=aggregate;if(aggregate)f.case_enabled.checked=false;d.querySelector('[data-case-controls]').hidden=!f.case_enabled.checked;}
